/// @brief 参考轨迹点结构体
struct RefTrajPoint {
  double t = 0.0;         /// @brief 时间
  double a = 0.0;         /// @brief 加速度
  double v = 0.0;         /// @brief 速度
  double s = 0.0;         /// @brief s 坐标
  double l = 0.0;         /// @brief l 坐标
  double x = 0.0;         /// @brief x 坐标
  double y = 0.0;         /// @brief y 坐标
  double z = 0.0;         /// @brief z 坐标
  double yaw = 0.0;       /// @brief 航向角
  double yaw_rate = 0.0;  /// @brief 航向角速度
};

/// @brief 参考轨迹辅助信息：特征点结构体
struct RefTargetPoint {
  double t = -1.0;  /// @brief 时间
  double s = 0.0;  /// @brief s 坐标
  double l = 0.0;  /// @brief l 坐标
  double x = 0.0;  /// @brief x 坐标
  double y = 0.0;  /// @brief y 坐标
  void Reset() {
    t = -1.0;
    s = 0.0;
    l = 0.0;
    x = 0.0;
    y = 0.0;
  }
  void Set(const RefTargetPoint& ref_traj_point) {
    t = ref_traj_point.t;
    s = ref_traj_point.s;
    l = ref_traj_point.l;
    x = ref_traj_point.x;
    y = ref_traj_point.y;
  }
};

/// @brief 参考轨迹信息结构体
struct RefTrajInfo {
  double traj_len = 0.0;                    /// @brief 轨迹长度
  double traj_duration = 0.0;               /// @brief 轨迹持续时间
  std::vector<RefTrajPoint> traj_points{};  /// @brief 轨迹点列表
  bool use_ref_longitudinal = false;        /// @brief 是否使用参考纵向轨迹（t, a, v, s）
  bool use_ref_lateral = false;             /// @brief 是否使用参考横向轨迹（s, l）
  RefTargetPoint target_point;              /// @brief 目标点
  RefTargetPoint last_target_point;         /// @brief 上一帧目标点
};

