// using MCTSKeyObstacles = std::unordered_map<
//     std::string, std::tuple<float, LongitudinalOdTag>> /*hwt, od_long_tag*/;
struct MCTSKeyObstacle {
  std::string id = "";     /// @brief 障碍物id
  float safe_hwt = 0.75f;  /// @brief 安全距离
  float safe_coeff = 1.0f;  /// @brief 安全系数
  float min_safe_dis = 0.0f;  /// @brief 最小安全距离
  float s = 0.0f;          /// @brief 障碍物在目标参考线上的s坐标
  LongitudinalOdTag tag =
      LongitudinalOdTag::INVALID;  /// @brief 障碍物初步纵向决策结果
  ObstacleBelongInLane belong_in_lane = ObstacleBelongInLane::UNKNOWN;
  MCTSKeyObstacle() = default;
  MCTSKeyObstacle(const std::string& id, const float s,
                  const LongitudinalOdTag& tag)
      : id(id), s(s), tag(tag) {}
  MCTSKeyObstacle(const std::string& id, const float s,
                  const LongitudinalOdTag& tag, const float safe_hwt)
      : id(id), s(s), tag(tag), safe_hwt(safe_hwt) {}
  MCTSKeyObstacle(const std::string& id, const float s,
                  const LongitudinalOdTag& tag, const float safe_hwt,
                  const ObstacleBelongInLane& belong_in_lane)
      : id(id),
        s(s),
        tag(tag),
        safe_hwt(safe_hwt),
        belong_in_lane(belong_in_lane) {}
  bool operator<(const MCTSKeyObstacle& other) const { return s < other.s; }

  MCTSKeyObstacle(const std::string& id, const float s,
                  const LongitudinalOdTag& tag, const float safe_hwt,
                  const float safe_coeff)
      : id(id), s(s), tag(tag), safe_hwt(safe_hwt), safe_coeff(safe_coeff) {}

  MCTSKeyObstacle(const std::string& id, const float s,
                  const LongitudinalOdTag& tag, const float safe_hwt,
                  const float safe_coeff,
                  const ObstacleBelongInLane& belong_in_lane,
                  const float min_safe_dis)
      : id(id),
        s(s),
        tag(tag),
        safe_hwt(safe_hwt),
        safe_coeff(safe_coeff),
        belong_in_lane(belong_in_lane),
        min_safe_dis(min_safe_dis) {}
};

using MCTSKeyObstacles = std::unordered_map<std::string, MCTSKeyObstacle>;

using MCTSKeyObstaclesInfo = std::unordered_map<MCTSScenario, MCTSKeyObstacles>;
/**
 * @brief MCTS算法计算的车道变换安全性结果结构体
 *
 * 该结构体存储蒙特卡洛树搜索(MCTS)算法对车道变换各状态间跳转安全性的判断结果，
 * 为车道变换状态机(LaneChangeFsm)的状态转换提供决策依据。所有安全标志默认初始化为false。
 **/
struct LaneChangeMctsResult {
  /**
   * @brief 从ACTIVE状态切换到CHANGING状态的安全性
   * 当MCTS算法判定当前可以开始执行车道变换时设为true
   */
  bool active_to_changing_safe = false;

  /**
   * @brief 从ATTEMPT状态切换到CHANGING状态的安全性
   * 当MCTS算法判定当前可以开始执行车道变换时设为true
   */
  bool attempt_to_changing_safe = false;

  /**
   * @brief 继续保持CHANGING状态的安全性
   * 当MCTS算法判定当前应继续执行车道变换过程时设为true
   */
  bool continue_changing_safe = false;

  /**
   * @brief 从CHANGING状态切换到HOLD状态的安全性
   * 当MCTS算法判定需要暂停车道变换并保持当前位置时设为true
   */
  bool changing_to_hold_safe = false;

  /**
   * @brief 从CHANGING状态直接切换到RETURN状态的安全性
   * 当MCTS算法判定需要立即终止车道变换并返回原车道时设为true
   */
  bool changing_to_return_safe = false;

  /**
   * @brief 从HOLD状态切换回CHANGING状态的安全性
   * 当MCTS算法判定可以从暂停状态继续执行车道变换时设为true
   */
  bool hold_to_changing_safe = false;

  /**
   * @brief 从HOLD状态切换到RETURN状态的安全性
   * 当MCTS算法判定需要从暂停状态返回原车道时设为true
   */
  bool hold_to_return_safe = false;

  /**
   * @brief 继续保持HOLD状态的安全性
   * 当MCTS算法判定需要继续暂停车道变换过程时设为true
   */
  bool continue_hold_safe = false;

  /**
   * @brief 继续保持RETURN状态的安全性
   * 当MCTS算法判定需要继续执行返回原车道过程时设为true
   */
  bool return_safe = false;

  /**
   * @brief 完成车道变换进入FINISH状态的安全性
   * 当MCTS算法判定车道变换已成功完成时设为true
   */
  bool finish_safe = false;

  MCTSKeyObstaclesInfo mcts_key_agents_info;
  LaneChangeMctsResult() = default;
};

/**
 * @brief 目标点创建场景枚举类型
 * @details
 * 定义GenerateGoalPoints函数创建目标点的具体场景，用于轨迹规划和状态机决策
 */
enum class GoalPointScenario {
  UNKNOWN = 0,
  KEEP_LANE = 1,
  NUDGE = 2,
  ACTIVE_TO_CHANGING = 3,
  CHANGING = 4,
  CHANGING_TO_HOLD = 5,
  CHANGING_TO_RETURN = 6,
  HOLD = 7,
  HOLD_TO_CHANGING = 8,
  HOLD_TO_RETURN = 9,
  RETURN = 10,
  FINISH = 11,
  MERGE = 12,
  ATTEMPT_TO_CHANGING = 13,
};
/**
 * @brief 目标点结构体
 * @details 包含坐标信息和创建场景类型
 */
struct MCTSGoalPoint {
  double s = 0.0;              ///< s坐标
  double l = 0.0;              ///< l坐标
  double v = 0.0;              ///< 速度
  double t = 0.0;              ///< 时间
  double x = 0.0;              ///< x坐标
  double y = 0.0;              ///< y坐标
  GoalPointScenario scenario;  ///< 创建场景类型
  MCTSGoalPoint(double s, double l, double v, double t,
                GoalPointScenario scenario)
      : s(s), l(l), v(v), t(t), x(x), y(y), scenario(scenario) {}
  MCTSGoalPoint()
      : s(0.0),
        l(0.0),
        v(0.0),
        t(0.0),
        x(0.0),
        y(0.0),
        scenario(GoalPointScenario::UNKNOWN) {}
};

